"""Block 4: output/key_numbers.md. Every number is computed from data/, eval/ and output/ (nothing typed by hand).
Run last: python generate_postings.py && python grouping.py && python analyze_patterns.py && python key_numbers.py"""
import json, os, re
import pandas as pd

HERE = os.path.dirname(os.path.abspath(__file__))
J = lambda *p: json.load(open(os.path.join(HERE, *p), encoding="utf-8"))
df = pd.read_csv(os.path.join(HERE, "data", "postings.csv"), keep_default_na=False)
pat, siz, val, ev = J("output", "patterns.json"), J("output", "sizing.json"), J("output", "value.json"), J("eval", "grouping_eval.json")
P = pat["patterns"]; pid = {p["pattern_id"]: p for p in P}
df["mi"] = (df.date.str[:4].astype(int) - 2025) * 12 + df.date.str[5:7].astype(int) - 11
MONTHS = ["Nov 25", "Dec 25", "Jan 26", "Feb 26", "Mar 26", "Apr 26", "May 26", "Jun 26", "Jul 26", "Aug 26", "Sep 26", "Oct 26"]
N = len(df); BKS = [f"B{i}" for i in range(1, 7)]
f0 = lambda x: f"{x:,.0f}"; f1 = lambda x: f"{x:,.1f}"; pc = lambda x, d=1: f"{x*100:.{d}f} %"
KILL = 2.0
L = []
def add(*lines): L.extend(lines)

add("# Key numbers: pattern suggestions demo for a bookkeeping office",
    "",
    "> **ALL DATA ARE SYNTHETIC.** The office 'Nordkyst Regnskab', its 180 clients, 6 bookkeepers and every posting are generated by `generate_postings.py` (seed 42). "
    "Nothing here is measured from a real accounting office or any real product. The numbers show what the method could do under the stated assumptions; they are not evidence about reality. "
    "Time per touch is an assumption, not a measurement.",
    "", f"Data: {f0(N)} postings, 180 clients (72 small service, 36 retail, 36 holding, 36 trades), Nov 2025 to Oct 2026. Patterns are found on Nov-Apr and backtested on May-Oct.", "")

# 1 ---------------------------------------------------------------
h = df.handling.value_counts()
add("## 1. Automation today", "",
    f"- **Automated to some degree: {pc((df.handling != 'manual').mean())}** (suggestion_accepted {pc(h['suggestion_accepted']/N)}, rule_to_journal {pc(h['rule_to_journal']/N)}, rule_posted {pc(h['rule_posted']/N)}); manual {pc(h['manual']/N)}.",
    f"- **Posted without a person (rule_posted): {pc(h['rule_posted']/N)}.** {df[df.handling.isin(['rule_posted','rule_to_journal'])].client_id.nunique()} of 180 clients (15 %) have any rule.",
    "- *Means:* two thirds of postings are prepared by the system, but only one in ten reaches the books without a person touching it. Automation stops before the finish line.",
    "- *Rests on:* the case fact (67 % automation) and a calibration of the generator to ~10 % rule_posted and ~15 % of clients with rules. rule_to_journal exists only on bank postings. No real rule data was used.", "")

# 2 ---------------------------------------------------------------
tpc = df[df.touched].groupby("mi").size() / 180
cm = df[df.touched].groupby(["client_id", "mi"]).size().unstack(fill_value=0)
add("## 2. Touches per client per month (the case's +-0)", "",
    "| " + " | ".join(MONTHS) + " |", "|" + "---|" * 12, "| " + " | ".join(f1(v) for v in tpc) + " |", "",
    f"- **Mean {f1(tpc.mean())}, range {f1(tpc.min())} to {f1(tpc.max())} ({(tpc.max()/tpc.mean()-1)*100:.1f} % above the mean at the peak).** Across clients the 12-month average runs from {f1(cm.mean(axis=1).min())} (holding) to {f1(cm.mean(axis=1).max())} (busy retail).",
    "- *Means:* the series is flat, matching the case: three months in, hours per client have not moved. A touch is any posting not booked by a rule_posted rule.",
    "- *Rests on:* rules pre-date the window (no rule starts mid-year) and seasonality is deliberately mild (December about +4 %). A flat line is built into the generator.", "")

# 3 ---------------------------------------------------------------
tb = df[df.touched].groupby(["bookkeeper_id", "mi"]).size().unstack(fill_value=0)
add("## 3. Touches per bookkeeper per month", "", "| Bookkeeper | Mean | Min month | Max month | Per client |", "|---|---|---|---|---|")
for b in BKS: add(f"| {b} | {f0(tb.loc[b].mean())} | {f0(tb.loc[b].min())} | {f0(tb.loc[b].max())} | {f1(tb.loc[b].mean()/30)} |")
add("", f"- **Office total {f0(tb.sum().mean())} touches a month; per bookkeeper {f0(tb.mean(axis=1).min())} to {f0(tb.mean(axis=1).max())}.**",
    "- *Means:* the workload the patterns are measured against. Differences between bookkeepers come from how many retail clients they have (retail is about 2.5x busier than a service client).",
    "- *Rests on:* each bookkeeper has 30 clients: 12 service, 6 retail, 6 holding, 6 trades; the differences are therefore only random mix of rule-covered clients.", "")

# 4 ---------------------------------------------------------------
r, a = ev["rule_based"], ev["ai"]
add("## 4. Grouping bank texts into payees: rules vs AI", "",
    f"Both use `bank_text` only; `vendor_true` is the answer key. {ev['unique_texts_in_scope']} unique masked texts; counterparty transfers (customer and one-off supplier payments) are out of scope.", "",
    "| | Rule-based (regex) | AI (Claude Sonnet, one batch) |", "|---|---|---|",
    f"| Merges (two vendors in one group, dangerous) | {r['confusions']['merges']} | {a['confusions']['merges']} |",
    f"| Postings on the wrong side of a merge | {f0(r['confusions']['postings_in_merged_groups_wrong_side'])} | {f0(a['confusions']['postings_in_merged_groups_wrong_side'])} |",
    f"| Splits (one vendor in several groups, harmless) | {r['confusions']['splits']} vendors, {r['confusions']['extra_groups_from_splits']} extra groups | {a['confusions']['splits']} vendors, {a['confusions']['extra_groups_from_splits']} extra groups |",
    f"| Completeness (postings in the vendor's largest group) | {pc(r['completeness'])} | {pc(a['completeness'])} |",
    f"| Precision (postings) | {pc(r['precision_postings'],2)} | {pc(a['precision_postings'],2)} |",
    f"| Coverage (postings given a group) | {pc(r['coverage_postings'])} | {pc(a['coverage_postings'])} |", "",
    f"- **Selected method: {ev['selected_method'].replace('_',' ')}** (fewest merges, then highest precision). The only rule-based merge is {r['confusions']['merged_groups'][0]['group']} = {' + '.join(r['confusions']['merged_groups'][0]['vendors'])}.",
    "- *Means:* a merge would make one rule wrong for two payees, so it is the dangerous error; splits only create more, smaller patterns to approve. Rules split a lot (low completeness); AI consolidates.",
    "- *Rests on:* synthetic bank texts that are fairly recognisable (brand names, 3 to 6 spellings each). Real bank texts are messier, so the AI precision of 100 % is probably optimistic. The AI mapping is cached in `eval/ai_mapping.json` so the run can be reproduced without calling the model again.", "")

# 5 ---------------------------------------------------------------
rc = pd.Series([p["risk"] for p in P]).value_counts(); rent = [p for p in P if p["type"] == "rent"]
rrc = pd.Series([p["risk"] for p in rent]).value_counts()
add("## 5. Patterns by risk", "", "| Risk | Patterns | of which rent |", "|---|---|---|")
for k, lab in (("low", "Low"), ("medium", "Medium"), ("not_suggested", "Not suggested")): add(f"| {lab} | {rc.get(k,0)} | {rrc.get(k,0)} |")
ns = [p for p in P if p["risk"] == "not_suggested" and p["type"] != "rent"]
add("", f"- **{len(P)} patterns: {rc.get('low',0)} low, {rc.get('medium',0)} medium, {rc.get('not_suggested',0)} not suggested** ({len(rent)} are client-specific rent patterns).",
    f"- Not suggested supplier patterns: " + "; ".join(f"{p['vendor_label']} {p['hit_rate']*100:.1f} %" for p in sorted(ns, key=lambda p: p['hit_rate'])) + ".",
    "- *Means:* low = backtest hit rate >= 95 %, average amount under 1,000 kr., no special VAT; medium = >= 95 % but larger amounts or special VAT or revenue (card settlements, Lemvigh-Mueller, most rent); not suggested = under 95 %, usually because clients book the same payee to different accounts.",
    "- *Rests on:* the 95 % and 1,000 kr. thresholds (my choice), patterns needing >= 3 touched postings per client in Nov-Apr with one consistent account, and a backtest on May-Oct only. About 3 % of human bookings sit on a neighbouring account by construction, which caps hit rates near 97-98 %.", "")

# 6 ---------------------------------------------------------------
sc = siz["scenarios"]; mods = siz["minutes"]
NM = {"split": "Suggestion cheaper", "equal": "Touch cost equal"}
add("## 6. Time saved: three scenarios, two minute models", "",
    "Scenarios: **Ceiling** = every pattern with hit rate >= 95 %, all approved. **Expected** = hit rate >= 95 %, no card settlements, no special VAT, 50 % approved. **Conservative** = the same patterns, 30 % approved.",
    f"Minutes: **Touch cost equal** (default) = every touch costs the same: {mods['equal']['low']['manual']} / {mods['equal']['mid']['manual']} / {mods['equal']['high']['manual']} min (low / mid / high). "
    f"**Suggestion cheaper** = a suggestion or journal touch costs half of a manually touched posting: {mods['split']['low']['suggestion_accepted']} / {mods['split']['mid']['suggestion_accepted']} / {mods['split']['high']['suggestion_accepted']} min against {mods['split']['low']['manual']} / {mods['split']['mid']['manual']} / {mods['split']['high']['manual']} min. Mid is shown in bold, low to high in brackets.", "",
    "| Scenario | Touches saved / month | Share of touches | Model | Hours / bookkeeper / month | Hours / office / month (north star) |", "|---|---|---|---|---|---|")
for k, lab in (("ceiling", "Ceiling"), ("expected", "Expected"), ("conservative", "Conservative")):
    x = sc[k]
    for m in ("equal", "split"):
        ho = x["hours_office"][m]
        add(f"| {lab} ({x['n_patterns']} patterns) | {f0(x['saved_per_month_office'])} | {pc(x['mean_share_of_touches'])} | {NM[m]} | **{f1(ho['mid']/6)}** ({f1(ho['low']/6)} to {f1(ho['high']/6)}) | **{f0(ho['mid'])}** ({f0(ho['low'])} to {f0(ho['high'])}) |")
rtj = {k: sc[k]["hours_mid_from_rule_to_journal_ASSUMPTION"]["equal"] for k in sc if k != "kill_check"}
add("", "- **Office = one accounting office (AO), 6 bookkeepers.** The north star is hours saved per office per month; per bookkeeper is the same number divided by 6.",
    f"- **Assumption:** part of the gain comes from rule_to_journal postings (a bank workflow sends them to the journal today). Counting that gain requires a bank workflow that can post directly. At mid (Touch cost equal) it is {f1(rtj['ceiling'])} h (ceiling), {f1(rtj['expected'])} h (expected), {f1(rtj['conservative'])} h (conservative) per office per month.",
    f"- *Means:* with Touch cost equal the saving is the number of touches removed times {mods['equal']['mid']['manual']} minute; with Suggestion cheaper most removed touches were already cheap suggestions, so the saving is about 40 % smaller. The case's +-0 hints at the equal model.",
    "- *Rests on:* minutes per touch are assumed, not measured; 100 % of pattern postings that match would be booked right at 95-99 % accuracy; approval shares of 50 % and 30 % are guesses; touches saved are averaged over May-Oct.", "")

# 7 ---------------------------------------------------------------
add("## 7. Kill check (2 hours per bookkeeper per month)", "",
    "Mean hours per bookkeeper per month at mid minutes; the 2 h line is the kill threshold.", "",
    "| Scenario | Touch cost equal | Suggestion cheaper |", "|---|---|---|")
below = []
for k, lab in (("ceiling", "Ceiling"), ("expected", "Expected"), ("conservative", "Conservative")):
    cells = []
    for m in ("equal", "split"):
        hs = [sc[k]["per_bookkeeper"][b]["hours"][m]["mid"] for b in BKS]
        mean = sum(hs) / 6; nb = sum(h < KILL for h in hs)
        if mean < KILL: below.append(f"{lab} / {NM[m]}")
        cells.append(f"{f1(mean)} h, {'**BELOW**' if mean < KILL else 'above'} ({nb} of 6 bookkeepers under 2 h)")
    add(f"| {lab} | {cells[0]} | {cells[1]} |")
ck = sc["kill_check"]
be = {m: KILL / (sc["expected"]["hours_office"][m]["mid"] / 6 / sc["expected"]["approval_share"]) for m in ("equal", "split")}
add("", f"- **Below 2 h: {', '.join(below) if below else 'none'}.** The kill rule as defined (conservative scenario) gives **{ck['equal']['verdict']}** with Touch cost equal and **{ck['split']['verdict']}** with Suggestion cheaper.",
    f"- **Break-even:** the expected pattern set clears 2 h per bookkeeper only if about {be['equal']*100:.0f} % of its patterns are approved with Touch cost equal, and about {be['split']*100:.0f} % with Suggestion cheaper (the scenarios assume 50 % and 30 %).",
    "- *Means:* at 1 minute per touch the idea is marginal: it clears the line only when roughly half of the safe patterns are approved (equal) and not at all at 30 % adoption; if suggestions are cheaper than manual touches the case is clearly below the line unless nearly every safe pattern is approved.",
    "- *Rests on:* the same assumptions as number 6; the threshold of 2 h per bookkeeper per month is a set test, not derived. The break-even assumes saved hours scale linearly with the share of approved patterns.", "")

# 8 ---------------------------------------------------------------
t = df[df.touched & (df.mi >= 6)]
tail = t.bank_text.str.upper().str.match(r"^(OVERF\. FRA|OVERF\. TIL|BETALING|FI )")
sp = (t.special_vat != "") & ~tail
nT = len(t); ceil_share = sc["ceiling"]["mean_share_of_touches"]
rest = 1 - tail.mean() - sp.mean() - ceil_share
tt = df[df.touched]; tail12 = tt.bank_text.str.upper().str.match(r"^(OVERF\. FRA|OVERF\. TIL|BETALING|FI )")
add("## 8. What stays manual", "", "Share of all touches, May-Oct 2026:", "",
    f"| Group | Share of touches |", "|---|---|",
    f"| Long tail: customer and one-off supplier payments (no cross-portfolio pattern) | {pc(tail.mean())} |",
    f"| special_vat: representation, EU purchases, mixed use (never in a suggestion) | {pc(sp.mean())} |",
    f"| Removed if every pattern >= 95 % is approved (ceiling) | {pc(ceil_share)} |",
    f"| Other: patterns under 95 %, no history, misses | {pc(rest)} |", "",
    f"- **Long tail {pc(tail.mean())} + special_vat {pc(sp.mean())} = {pc(tail.mean()+sp.mean())} of touches lie outside what this mechanism targets.** Over all 12 months the long tail is {pc(tail12.mean())}.",
    "- *Means:* patterns remove repeated payee postings; they do not touch one-off payments or postings needing a VAT judgement, which is why the ceiling is below 50 %.",
    "- *Rests on:* the long tail is identified from the bank text prefix (OVERF. FRA, BETALING, ...), special VAT from the generator's flag; the 'other' share is a remainder.", "")

# 9 ---------------------------------------------------------------
ms = val["months"]; before = [m["pct_auto_posted"] for m in ms[:6]]; after = [m["pct_auto_posted"] for m in ms[6:]]
tb0 = sum(m["touches_per_client"] for m in ms[:6]) / 6; tb1 = sum(m["touches_per_client"] for m in ms[6:]) / 6
ex = val["exception"]; ap = val["approved_patterns"]
add("## 9. Value over time: the 3 safest patterns plus one rent workflow", "",
    f"- **Posted without a person: {pc(sum(before)/6/100)} before (Nov-Apr), {pc(sum(after)/6/100)} after (May-Oct average; October {pc(after[-1]/100)}).** Touches per client per month {f1(tb0)} to {f1(tb1)}.",
    f"- Approved from May: " + ", ".join(f"{pid[a['pattern_id']]['vendor_label']} [{pid[a['pattern_id']]['group']}] ({pid[a['pattern_id']]['n_clients']} clients, {a['risk']})" for a in ap) + ".",
    f"- Corrections per month after approval: " + ", ".join(f"{m['corrections']:.0f}" for m in ms[6:]) + " (May to Oct).",
    f"- **Simulated exception: the rent workflow at {ex['client']} (bookkeeper B2) holds back one October payment.** Usual rent {ex['usual_amount']:,.0f} DKK from the same payee ({ex['rent_postings']} postings in 12 months); on {ex['date']} a payment of {ex['held_amount']:,.0f} DKK ({ex['ratio']:.1f}x) to a new payee arrives. The workflow holds it for that client only; the bookkeeper chooses Update workflow, Book as usual or Keep on hold.",
    "- *Means:* the approved workflows lift the share without a person by a few points and save about two touches per client a month; the rest of the value is in the 90 suggestions still waiting. An amount-and-payee check lets a workflow stop on one odd payment instead of booking it blindly.",
    "- *Rests on:* a simulation. Approval in May, approved patterns auto-post every matching touched posting, corrections = actual backtest misses. The held payment is an invented overlay (not in postings.csv, not counted in any series); the amount is 3x the client's own median rent.", "")

# 10 --------------------------------------------------------------
B = "B2"
appr = {a["pattern_id"] for a in val["approved_patterns"]}
mine = lambda p: [c for c in p["clients"] if c.startswith("C") and BKMAP[c] == B]
BKMAP = df.drop_duplicates("client_id").set_index("client_id").bookkeeper_id.to_dict()
RO = {"low": 0, "medium": 1, "not_suggested": 2}
def my_saved(p): return sum(p["saved_by_client"].get(c, 0) for c in p["clients"] if BKMAP[c] == B)
openp = [p for p in P if p["status"] == "suggested" and p["pattern_id"] not in appr and my_saved(p) > 0]
nonrent = sorted([p for p in openp if p["type"] != "rent"], key=lambda p: (RO[p["risk"]], p["safety_rank"]))
rent_open = [p for p in openp if p["type"] == "rent"]
touch_b = int(((df.mi == 11) & df.touched & (df.bookkeeper_id == B)).sum())
Y = sum(my_saved(p) for p in openp); top3 = nonrent[:3]; X = sum(my_saved(p) for p in top3)
add(f"## 10. Demo numbers for {B} (what the prototype shows on first load)", "",
    f"- **Nudge (Task overview):** \"{len(top3)} patterns could remove {f0(X)} touches across your clients this month\" ({', '.join(p['vendor_label'] if p['type']!='revenue' else p['group'] for p in top3)}).",
    f"- **Suggestions headline:** \"This month: {f0(touch_b)} manual touches across your 30 clients. {f0(Y)} could be handled by patterns you approve.\"",
    f"- **With patterns box:** review {min(len(nonrent),8)+(1 if rent_open else 0)} patterns ({min(len(nonrent),8)} suppliers/fees plus one rent line covering {len(rent_open)} clients).",
    "- **Top suggestions, safest first (hit rate, her clients of all):** " + "; ".join(f"{p['vendor_label']} ({p['risk']}, {p['hit_rate']*100:.1f} %, {len([c for c in p['clients'] if BKMAP[c]==B])} of {p['n_clients']})" for p in nonrent[:8]) + ".",
    f"- *Means:* the story a bookkeeper sees: about {f0(Y)} of her {f0(touch_b)} monthly touches ({Y/touch_b*100:.0f} %) are repeats that nine decisions could take over.",
    "- *Rests on:* the state after the approved workflows (Clearhaus fees, Teya card fees, Circle K and one rent workflow are no longer open); touches counted for October; 'could be handled' uses May-Oct average savings, so it is an estimate, not an October count. Clearhaus fees is the safest pattern overall but is already approved, so it is not in B2's open list.", "")
add("---", "Reproduce: `python generate_postings.py && python grouping.py && python analyze_patterns.py && python build_prototype.py && python key_numbers.py`. Prototype: `prototype/index.html` (append `#selftest` to run the click test).")
os.makedirs(os.path.join(HERE, "output"), exist_ok=True)
open(os.path.join(HERE, "output", "key_numbers.md"), "w", encoding="utf-8").write("\n".join(L) + "\n")
print("\n".join(L))
